    ov_loaded: ["Plan eingesetzt (ungefähre Grösse). Bitte mit «Passpunkte setzen» ausrichten.", "Plan inséré (taille approximative). Aligner avec «Points de calage».", "Pianta inserita (dimensione approssimativa). Allineare con «Punti di appoggio».", "Plan inserted (approximate size). Please align with “Set control points”."],
    ov_loadedAuto: ["Plan eingesetzt, Massstab 1:{r} automatisch gesetzt. Lage und Drehung mit «Passpunkte setzen» ausrichten.", "Plan inséré, échelle 1:{r} fixée automatiquement. Aligner position et rotation avec «Points de calage».", "Pianta inserita, scala 1:{r} impostata automaticamente. Allineare posizione e rotazione con «Punti di appoggio».", "Plan inserted, scale 1:{r} set automatically. Align position and rotation with “Set control points”."],
    ov_g1: ["Passpunkt 1: Punkt auf dem Plan anklicken (z. B. Gebäudeecke).", "Point de calage 1: cliquer un point du plan (p. ex. coin de bâtiment).", "Punto di appoggio 1: cliccare un punto sulla pianta (p. es. angolo edificio).", "Control point 1: click a point on the plan (e.g. building corner)."],
    ov_g2: ["Passpunkt 1: jetzt die richtige Stelle auf der Karte anklicken.", "Point de calage 1: cliquer maintenant le bon endroit sur la carte.", "Punto di appoggio 1: ora cliccare il punto giusto sulla carta.", "Control point 1: now click the right spot on the map."],
